"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { register } from "../api/auth";
import Avatar from "@/components/ui/avatar";

import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardFooter,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

export default function RegisterPage() {
  const router = useRouter();

  const [formData, setFormData] = useState({
    fullName: "",
    email: "",
    password: "",
    role: "patient",
    phone: "",
    gender: "",
    age: "",
    specialization: "",
    qualifications: "",
    experience: "",
    availability: "",
    medicalHistory: "",
    bloodGroup: "",
  });

  const [error, setError] = useState("");

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSelect = (name, value) => {
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    try {
      const res = await register(formData);
      console.log("res", res);
      
      if (!res.message == "patient registered successfully") 
        throw new Error(res.data?.message || "Registration failed");
      router.push("/login");
    } catch (err) {
      setError(err.message);
    }
  };

  const isDoctor = formData.role === "doctor";

  return (
    <div className="flex  items-center justify-center min-h-screen bg-gray-100 p-4">
      <Card className="w-full max-w-md">
        <CardHeader>
          <CardTitle className="text-2xl">Register</CardTitle>
        </CardHeader>

        <form onSubmit={handleSubmit}>
          <CardContent className="space-y-4">
  {error && <p className="text-sm text-red-500">{error}</p>}
  <div className="grid grid-cols-2 gap-4">
    <div className="flex flex-col gap-1">
      <Label htmlFor="fullName" className="mb-1">Full Name</Label>
      <Input id="fullName" name="fullName" value={formData.fullName} onChange={handleChange} required />
    </div>
    <div className="flex flex-col gap-1">
      <Label htmlFor="email" className="mb-1">Email</Label>
      <Input id="email" type="email" name="email" value={formData.email} onChange={handleChange} required />
    </div>
    <div className="flex flex-col gap-1">
      <Label htmlFor="password" className="mb-1">Password</Label>
      <Input id="password" type="password" name="password" value={formData.password} onChange={handleChange} required />
    </div>
    <div className="flex flex-col gap-1">
      <Label htmlFor="phone" className="mb-1">Phone</Label>
      <Input id="phone" name="phone" value={formData.phone} onChange={handleChange} />
    </div>
    <div className="flex flex-col gap-1">
      <Label className="mb-1">Gender</Label>
      <Select value={formData.gender} onValueChange={(val) => handleSelect("gender", val)}>
        <SelectTrigger>
          <SelectValue placeholder="Select Gender"/>
        </SelectTrigger>
        <SelectContent>
          <SelectItem value="male">Male</SelectItem>
          <SelectItem value="female">Female</SelectItem>
          <SelectItem value="other">Other</SelectItem>
        </SelectContent>
      </Select>
    </div>
    <div className="flex flex-col gap-1">
      <Label htmlFor="age" className="mb-1">Age</Label>
      <Input id="age" type="number" name="age" value={formData.age} onChange={handleChange} />
    </div>
    <div className="flex flex-col gap-1">
      <Label className="mb-1">Role</Label>
      <Select value={formData.role} onValueChange={(val) => handleSelect("role", val)}>
        <SelectTrigger>
          <SelectValue placeholder="Select Role" />
        </SelectTrigger>
        <SelectContent>
          <SelectItem value="patient">Patient</SelectItem>
          <SelectItem value="doctor">Doctor</SelectItem>
        </SelectContent>
      </Select>
    </div>
  </div>

  {/* === DOCTOR FIELDS === */}
  {isDoctor && (
    <>
      <div className="flex flex-col gap-4">
        <div className="flex items-center gap-4">
          <Label htmlFor="specialization" className="w-40 mb-0">Specialization</Label>
          <Input id="specialization" name="specialization" value={formData.specialization} onChange={handleChange} className="flex-1" />
        </div>
        <div className="flex items-center gap-4">
          <Label htmlFor="qualifications" className="w-40 mb-0">Qualifications</Label>
          <Input id="qualifications" name="qualifications" value={formData.qualifications} onChange={handleChange} className="flex-1" placeholder="comma separated" />
        </div>
        <div className="flex items-center gap-4">
          <Label htmlFor="experience" className="w-40 mb-0">Experience (years)</Label>
          <Input id="experience" name="experience" type="number" value={formData.experience} onChange={handleChange} className="flex-1" />
        </div>
        <div className="flex items-center gap-4">
          <Label htmlFor="availability" className="w-40 mb-0">Availability</Label>
          <Input id="availability" name="availability" value={formData.availability} onChange={handleChange} className="flex-1" placeholder="e.g. Mon-Fri 10am-2pm" />
        </div>
      </div>
    </>
  )}

  {/* === PATIENT FIELDS === */}
  {!isDoctor && (
    <>
      <div className="flex flex-col gap-4">
        <div className="flex items-center gap-4">
          <Label htmlFor="medicalHistory" className="w-40 mb-0">Medical History</Label>
          <Input id="medicalHistory" name="medicalHistory" value={formData.medicalHistory} onChange={handleChange} className="flex-1" placeholder="comma separated" />
        </div>
        <div className="flex items-center gap-4">
          <Label className="w-40 mb-0">Blood Group</Label>
          <Select value={formData.bloodGroup} onValueChange={(val) => handleSelect("bloodGroup", val)}>
            <SelectTrigger className="flex-1">
              <SelectValue placeholder="Select Blood Group" />
            </SelectTrigger>
            <SelectContent>
              {["A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-"].map((bg) => (
                <SelectItem key={bg} value={bg}>{bg}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>
    </>
  )}
</CardContent>

          <CardFooter className="flex flex-col gap-2 mt-3.5">
            <Button type="submit" className="w-full">
              Register
            </Button>
            <p className="text-sm text-muted-foreground text-center">
              Already have an account?{" "}
              <a href="/login" className="text-blue-600 hover:underline">
                Login
              </a>
            </p>
          </CardFooter>
        </form>
      </Card>
    </div>
  );
}
